const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const cors = require('cors');
const { body, query, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet()); // Security headers

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

app.use(limiter);

// CORS configuration - restrict to known origins in production
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : '*', // Allow all in development
}));

// Request parsing with size limits to prevent overflow attacks
app.use(express.json({
  limit: '10kb' // Limit request body size
}));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation middleware for users endpoint (if needed for query parameters)
const validateUsersQuery = [
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be an integer between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer'),
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        errors: errors.array().map(error => ({
          field: error.param,
          message: error.msg
        })) 
      });
    }
    next();
  }
];

// Health check endpoint
app.get('/health', [
  // Validate no query parameters are provided
  (req, res, next) => {
    if (Object.keys(req.query).length > 0) {
      return res.status(400).json({ 
        error: 'Health check endpoint does not accept query parameters' 
      });
    }
    next();
  }
], (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint with input validation
app.get('/users', validateUsersQuery, (req, res) => {
  try {
    // Sample data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Simple filtering based on query parameters
    let filteredUsers = users;

    if (req.query.limit) {
      const limit = parseInt(req.query.limit);
      filteredUsers = filteredUsers.slice(0, limit);
    }

    if (req.query.offset) {
      const offset = parseInt(req.query.offset);
      filteredUsers = filteredUsers.slice(offset);
    }

    res.json({
      data: filteredUsers,
      total: users.length,
      limit: req.query.limit ? parseInt(req.query.limit) : null,
      offset: req.query.offset ? parseInt(req.query.offset) : null
    });

  } catch (error) {
    console.error('Error processing users request:', error);
    res.status(500).json({ 
      error: 'Internal server error'
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.originalUrl} not found`
  });
});

// Global error handling middleware
app.use((error, req, res, next) => {
  console.error('Uncaught error:', error);

  // Handle specific error types
  if (error.name === 'ValidationError') {
    return res.status(400).json({
      error: 'Validation error',
      details: error.message
    });
  }

  // For all other errors
  res.status(500).json({ 
    error: 'Internal server error'
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

