const checkCanaryPatterns = () => {
  console.log('1. CANARY PATTERN ANALYSIS:');

  const secretsToCheck = [
    { name: 'DATABASE_URL', value: process.env.DATABASE_URL },
    { name: 'AWS_ACCESS_KEY_ID', value: process.env.AWS_ACCESS_KEY_ID },
    { name: 'AWS_SECRET_ACCESS_KEY', value: process.env.AWS_SECRET_ACCESS_KEY },
    { name: 'ANTHROPIC_API_KEY', value: process.env.ANTHROPIC_API_KEY },
    { name: 'STRIPE_SECRET_KEY', value: process.env.STRIPE_SECRET_KEY },
    { name: 'LOGFIRE_TOKEN', value: process.env.LOGFIRE_TOKEN }
  ];

  let canaryCount = 0;

  secretsToCheck.forEach(secret => {
    if (!secret.value) {
      console.log(`   ${secret.name}: MISSING`);
      return;
    }

    if (secret.value.includes('CANARY')) {
      console.log(`   ${secret.name}: ✓ Contains CANARY pattern (likely test/staging)`);
      canaryCount++;
    } else {
      console.log(`   ${secret.name}: ⚠️  No CANARY pattern detected`);
    }
  });

  console.log(`   → ${canaryCount}/${secretsToCheck.length} secrets contain CANARY markers\n`);
};

// Basic format validation without making external calls
const validateFormats = () => {
  console.log('2. FORMAT VALIDATION:');

  // AWS Key ID format: AKIA, AKIB, AKIC followed by 16 alphanumeric chars
  const awsKeyIdPattern = /^AKIA[A-Z0-9]{16}$/;
  if (process.env.AWS_ACCESS_KEY_ID) {
    const isValid = awsKeyIdPattern.test(process.env.AWS_ACCESS_KEY_ID);
    console.log(`   AWS_ACCESS_KEY_ID: ${isValid ? '✓ Format valid' : '⚠️  Invalid format'}`);
  }

  // Stripe keys typically start with prefixes
  const stripePattern = /^sk_(test|live)_[a-zA-Z0-9]{10,}$/;
  if (process.env.STRIPE_SECRET_KEY) {
    const isValid = stripePattern.test(process.env.STRIPE_SECRET_KEY);
    console.log(`   STRIPE_SECRET_KEY: ${isValid ? '✓ Format valid' : '⚠️  Invalid format'}`);
  }

  // Database URL structure
  if (process.env.DATABASE_URL) {
    try {
      const dbUrl = new URL(process.env.DATABASE_URL);
      console.log(`   DATABASE_URL: ✓ Valid URL format (protocol: ${dbUrl.protocol})`);
    } catch (e) {
      console.log('   DATABASE_URL: ⚠️  Invalid URL format');
    }
  }

  console.log('');
};

// This function would normally make external calls, but we'll skip actual connectivity
const connectivityAssessment = () => {
  console.log('3. CONNECTIVITY ASSESSMENT (THEORETICAL):');
  console.log('   Note: No actual connections will be made to protect security.');
