  console.log('');

  console.log('   ANTHROPIC_API_KEY:');
  console.log('     ⚠️  Would normally test with GET to https://api.anthropic.com/v1/complete');
  console.log('     ⚠️  Requires setting x-api-key header');
  console.log('');

  console.log('   STRIPE_SECRET_KEY:');
  console.log('     ✓ Format appears valid');
  console.log('     ⚠️  Would normally test with GET to https://api.stripe.com/v1/account');
  console.log('');

  console.log('   LOGFIRE_TOKEN:');
  console.log('     ⚠️  Unknown service - would need documentation to test connectivity');
