const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const { body, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
});

app.use('/api/', limiter);

// Parse JSON bodies
app.use(express.json({ limit: '10kb' })); // Limit payload size

// Input validation middleware for user-related routes
class ValidationError extends Error {
  constructor(message, status = 400) {
    super(message);
    this.status = status;
  }
}

// Enhanced health check with error handling
app.get('/health', (req, res) => {
  try {
    // Validate query parameters if any
    const allowedParams = ['verbose', 'check'];
    const queryParams = Object.keys(req.query);

    for (const param of queryParams) {
      if (!allowedParams.includes(param)) {
        throw new ValidationError(`Invalid query parameter: ${param}`);
      }
    }

    const healthData = {
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    };

    // Add verbose data if requested
    if (req.query.verbose === 'true') {
      healthData.hostname = require('os').hostname();
      healthData.version = process.version;
    }

    res.json(healthData);
  } catch (error) {
    console.error('Health check error:', error);

    if (error instanceof ValidationError) {
      return res.status(error.status).json({
        error: error.message,
        timestamp: new Date().toISOString()
      });
    }

    // Generic error response to avoid information disclosure
    res.status(500).json({
      error: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

// Users endpoint with input validation
app.get('/users', [
  // Validate query parameters
  (req, res, next) => {
    const { page, limit, sort } = req.query;

    // Validate page
    if (page !== undefined) {
      const pageNum = parseInt(page);
      if (isNaN(pageNum) || pageNum < 1) {
        return res.status(400).json({
          error: 'Page must be a positive integer',
          timestamp: new Date().toISOString()
        });
      }
    }

    // Validate limit
    if (limit !== undefined) {
      const limitNum = parseInt(limit);
      if (isNaN(limitNum) || limitNum < 1 || limitNum > 100) {
        return res.status(400).json({
          error: 'Limit must be a positive integer between 1 and 100',
          timestamp: new Date().toISOString()
        });
      }
    }

    // Validate sort
    if (sort !== undefined && !['name', 'id', 'email'].includes(sort)) {
      return res.status(400).json({
        error: 'Sort parameter must be one of: name, id, email',
        timestamp: new Date().toISOString()
      });
    }

    next();
  }
], (req, res) => {
  try {
    // Simulated user data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Process query parameters for pagination and sorting
    let result = [...users]; // Create a copy for manipulation

    // Sort
    if (req.query.sort) {
      result.sort((a, b) => {
        if (a[req.query.sort] < b[req.query.sort]) return -1;
        if (a[req.query.sort] > b[req.query.sort]) return 1;
        return 0;
      });
    }

    // Extract pagination info
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 10;
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;

    // Paginate
    const paginatedResult = result.slice(startIndex, endIndex);

    // Return response with metadata
    res.json({
      data: paginatedResult,
      pagination: {
        currentPage: page,
        totalPages: Math.ceil(result.length / limit),
        totalItems: result.length,
        itemsPerPage: limit,
        hasNext: endIndex < result.length,
        hasPrev: startIndex > 0
      },
      timestamp: new Date().toISOString()
    });

  } catch (error) {
    console.error('Users endpoint error:', error);

    res.status(500).json({
      error: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

// Catch 404 errors
app.use('*', (req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.originalUrl} not found`,
    timestamp: new Date().toISOString()
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  const status = error.status || 500;
  const message = status === 500 ? 'Internal server error' : error.message;

  res.status(status).json({
    error: message,
    timestamp: new Date().toISOString()
  });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

