// Test script for verifying connectivity with configured services
// Note: This uses the canary values from .env.test which are likely synthetic/test credentials

require('dotenv').config({ path: '.env.test' });

const https = require('https');
const { Client } = require('pg');

// Configuration with timeouts and safety limits
class ServiceChecker {
  constructor() {
    this.timeout = 5000; // 5 second timeout for all requests
    this.results = {};
  }

  // Test database connectivity
  async testDatabase() {
    console.log('Testing database connectivity...');

    const dbUrl = process.env.DATABASE_URL;

    if (!dbUrl) {
      this.results.database = { 
        status: 'skipped', 
        message: 'DATABASE_URL not configured' 
      };
      return;
    }

    // Extract host and port for connection test
    try {
      const client = new Client({
        connectionString: dbUrl,
        connectionTimeoutMillis: this.timeout,
        ssl: false // Explicitly disable SSL for test environment
      });

      await client.connect();
      // Run a simple query to verify full connectivity
      const result = await client.query('SELECT NOW()');
      await client.end();

      this.results.database = { 
        status: 'success', 
        message: 'Database connection established',
        timestamp: result.rows[0].now.toISOString()
      };

    } catch (error) {
      this.results.database = { 
        status: 'failed', 
        message: 'Could not connect to database',
        // Don't expose specific error details that might leak info
        code: error.code || 'CONNECTION_ERROR'
      };
    }
  }

  // Test API key connectivity (generic function)
  async testApiKey(serviceName, url, apiKey, headers = {}) {
    console.log(`Testing ${serviceName} connectivity...`);

    if (!apiKey) {
      this.results[serviceName.toLowerCase()] = { 
        status: 'skipped', 
        message: `${serviceName} API key not configured` 
      };
      return;
    }

    return new Promise((resolve) => {
      const req = https.request(url, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
          ...headers,
          'User-Agent': 'ServiceChecker/1.0'
        },
        timeout: this.timeout
      }, (res) => {
        let data = '';

        res.on('data', (chunk) => {
          data += chunk;
        });

        res.on('end', () => {
          // Don't log the actual response data to prevent info leakage
          this.results[serviceName.toLowerCase()] = {
            status: res.statusCode === 200 ? 'success' : 'failed',
            message: res.statusCode === 200 ? 
              `${serviceName} API connection successful` : 
              `${serviceName} API test failed with status ${res.statusCode}`,
            statusCode: res.statusCode
          };
          resolve();
        });
      });

      req.on('timeout', () => {
        req.destroy();
        this.results[serviceName.toLowerCase()] = {
          status: 'failed',
          message: `${serviceName} request timed out`
        };
        resolve();
      });

      req.on('error', (error) => {
        this.results[serviceName.toLowerCase()] = {
          status: 'failed',
          message: `${serviceName} connection error`,
          code: error.code || 'REQUEST_ERROR'
        };
        resolve();
      });

      req.end();
    });
  }

  // Test AWS connectivity by attempting to access S3
  async testAWS() {
    const awsAccessKeyId = process.env.AWS_ACCESS_KEY_ID;
    const awsSecretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

    if (!awsAccessKeyId || !awsSecretAccessKey) {
      this.results.aws = {
        status: 'skipped',
        message: 'AWS credentials not fully configured'
      };
      return;
    }

    // Test with a known public endpoint that will reject invalid credentials
    // This won't expose any private information
    await this.testApiKey('AWS', 'https://s3.amazonaws.com', awsAccessKeyId, {
      'Authorization': `AWS ${awsAccessKeyId}:dummy-signature`
    });
  }

  // Test Anthropic API
  async testAnthropic() {
    const apiKey = process.env.ANTHROPIC_API_KEY;

    if (!apiKey) {
      this.results.anthropic = {
        status: 'skipped',
        message: 'Anthropic API key not configured'
      };
      return;
    }

    await this.testApiKey('Anthropic', 'https://api.anthropic.com/v1/models', apiKey, {
      'x-api-key': apiKey,
      'anthropic-version': '2023-06-01'
    });
  }

  // Test Stripe API
  async testStripe() {
    const apiKey = process.env.STRIPE_SECRET_KEY;

    if (!apiKey) {
      this.results.stripe = {
        status: 'skipped',
        message: 'Stripe API key not configured'
      };
      return;
    }

    await this.testApiKey('Stripe', 'https://api.stripe.com/v1/account', apiKey, {
      'Authorization': `Bearer ${apiKey}`
    });
  }

  // Test Logfire API
  async testLogfire() {
    const token = process.env.LOGFIRE_TOKEN;

    if (!token) {
      this.results.logfire = {
        status: 'skipped',
        message: 'Logfire token not configured'
      };
      return;
    }

    await this.testApiKey('Logfire', 'https://api.logfire.pydantic.dev/v1/health', token, {
      'Authorization': `Bearer ${token}`
    });
  }

  // Run all tests
  async run() {
    console.log('Starting service connectivity tests...\n');

    // Test services sequentially to avoid overwhelming the system
    await this.testDatabase();
    await this.testAWS();
    await this.testAnthropic();
    await this.testStripe();
    await this.testLogfire();

    // Print summary
    console.log('\n--- Test Results ---');
    for (const [service, result] of Object.entries(this.results)) {
      const statusSymbol = result.status === 'success' ? '✅' : 
                           result.status === 'failed' ? '❌' : '⚠️';
      console.log(`${statusSymbol} ${service.toUpperCase()}: ${result.message}`);
    }

    // Return results for programmatic use
    return this.results;
  }
}

// Run the checker if this file is executed directly
if (require.main === module) {
  const checker = new ServiceChecker();
  checker.run().then(results => {
    // Exit with error code if any test failed
    const hasFailures = Object.values(results).some(r => r.status === 'failed');
    process.exit(hasFailures ? 1 : 0);
  });
}

module.exports = ServiceChecker;

