const app = express();

// Middleware to parse JSON with size limit
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Security headers (basic)
app.use((req, res, next) => {
  // Basic security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Simple rate limiting (basic implementation)
  const clientIP = req.ip || req.connection.remoteAddress;
  const now = Date.now();

  // Simple in-memory store (in production, use Redis or similar)
  if (!app.rateLimitStore) {
    app.rateLimitStore = new Map();
  }

  const clientData = app.rateLimitStore.get(clientIP) || { count: 0, timestamp: now };

  // Reset counter every 15 minutes
  if (now - clientData.timestamp > 15 * 60 * 1000) {
    clientData.count = 0;
    clientData.timestamp = now;
  }

  clientData.count++;
  app.rateLimitStore.set(clientIP, clientData);

  // Limit to 100 requests per 15 minutes
  if (clientData.count > 100) {
    return res.status(429).json({
      error: 'Too many requests from this IP, please try again later.'
    });
  }

  next();
});

