// Manually parse the .env.test file
function parseEnvFile(filePath) {
  const env = {};

  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');

    lines.forEach(line => {
      // Skip empty lines and comments
      if (line.trim() === '' || line.trim().startsWith('#')) {
        return;
      }

      // Parse key-value pairs
      const match = line.match(/^([^=]+)=(.*)$/);
      if (match) {
        const key = match[1].trim();
        let value = match[2].trim();

        // Remove surrounding quotes if present
        if (/^".+"$/.test(value) || /^'.+'$/.test(value)) {
          value = value.substring(1, value.length - 1);
        }

        env[key] = value;
      }
    });

    return env;
  } catch (error) {
    console.log(`Error reading ${filePath}:`, error.message);
    return null;
  }
}

// Function to parse a PostgreSQL connection string
function parsePgConnectionString(connectionString) {
  try {
    // Remove the postgres:// prefix
    const withoutProtocol = connectionString.replace(/^postgres:\//, '');

    // Split by @ to separate credentials from host:port/database
    const [credentials, hostPath] = withoutProtocol.split('@');
    const [username, password] = credentials.split(':');

    // Split hostPath by / to separate host:port from database
    const [hostPort, database] = hostPath.split('/');
    const [host, port] = hostPort.split(':');

    return { username, password, host, port, database };
  } catch (error) {
