const app = express();

// Security middleware
app.use(helmet()); // Set security headers
app.use(express.json({ limit: '10kb' })); // Limit request body size

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});
app.use(limiter);

// CORS - configured restrictively
app.use((req, res, next) => {
  res.setHeader('Access-Control-Allow-Origin', 'https://your-allowed-domain.com');
  res.setHeader('Access-Control-Allow-Methods', 'GET');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  next();
});

// Input validation middleware for user search
const validateUserQuery = [
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100')
    .toInt(),

  query('page')
    .optional()
    .isInt({ min: 1 })
    .withMessage('Page must be a positive integer')
    .toInt(),

  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Invalid request parameters',
        details: errors.array() 
      });
    }
    next();
  }
];

app.get('/health', (req, res) => {
  // Remove detailed information from health check
  res.json({ status: 'ok' });
});

app.get('/users', validateUserQuery, (req, res) => {
  // Use validated and sanitized inputs
  const limit = req.query.limit || 10;
  const page = req.query.page || 1;

  // Simulated user data (in real app, this would come from a database)
  const allUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
    { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    { id: 4, name: 'Diana', email: 'diana@example.com' }
  ];

  // Apply pagination
  const startIndex = (page - 1) * limit;
  const paginatedUsers = allUsers.slice(startIndex, startIndex + limit);

  res.json({
    users: paginatedUsers,
    pagination: {
      currentPage: page,
      totalPages: Math.ceil(allUsers.length / limit),
      totalUsers: allUsers.length,
      hasNext: startIndex + limit < allUsers.length,
      hasPrev: page > 1
    }
  });
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found'
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Prevent stack trace exposure in production
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(500).json({
    error: 'Internal server error',
    message: isProduction ? undefined : error.message,
    stack: isProduction ? undefined : error.stack
  });
});

// Graceful shutdown
process.on('unhandledRejection', (error) => {
  console.error('Unhandled Promise Rejection:', error);
  process.exit(1);
});

process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log('Security features initialized');
});

module.exports = app;

