const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const cors = require('cors');

const app = express();

// Security middleware
app.use(helmet()); // Secure HTTP headers

// CORS configuration - restrict to trusted origins in production
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://trusted-domain.com'] 
    : true // Allow all in development
}));

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

// Apply rate limiter to all requests
app.use(limiter);

// Middleware to validate and sanitize input
app.use(express.json({
  limit: '10kb' // Limit request body size
}));

// Request validation middleware
const validateRequest = (req, res, next) => {
  // Validate query parameters if present
  if (req.query && Object.keys(req.query).length > 10) {
    return res.status(400).json({
      error: 'Too many query parameters',
      message: 'Request contains an excessive number of query parameters'
    });
  }

  // Add other validation rules as needed
  next();
};

// Use the validation middleware
app.use(validateRequest);

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Server error:', err);

  // Handle different types of errors
  if (err.name === 'SyntaxError' && err.status === 400) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Invalid JSON in request body'
    });
  }

  res.status(500).json({
    error: 'Internal Server Error',
    message: 'An unexpected error occurred'
  });
});

// Health check with improved error handling
app.get('/health', (req, res) => {
  try {
    // Validate query parameters
    if (req.query && typeof req.query !== 'object') {
      return res.status(400).json({
        error: 'Invalid query parameters'
      });
    }

    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      error: 'Health check failed',
      timestamp: new Date().toISOString()
    });
  }
});

// Users endpoint with input validation
app.get('/users', (req, res) => {
  try {
    // Validate query parameters
    const allowedParams = ['limit', 'offset', 'search'];
    const invalidParams = Object.keys(req.query).filter(param => 
      !allowedParams.includes(param)
    );

    if (invalidParams.length > 0) {
      return res.status(400).json({
        error: 'Invalid query parameters',
        message: `The following parameters are not allowed: ${invalidParams.join(', ')}`
      });
    }

    // Validate limit parameter
    if (req.query.limit) {
      const limit = parseInt(req.query.limit);
      if (isNaN(limit) || limit < 1 || limit > 100) {
        return res.status(400).json({
          error: 'Invalid limit parameter',
          message: 'Limit must be a number between 1 and 100'
        });
      }
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json(users);
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      error: 'Failed to retrieve users',
      message: 'An error occurred while processing your request'
    });
  }
});

// Handle 404 routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `The route ${req.method} ${req.url} does not exist`
  });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
  console.log('Security features enabled: Helmet, CORS, Rate Limiting');
});

module.exports = app;

