/**
 * Environment validation script
 * This safely checks that required environment variables are present
 * without attempting to use or validate the actual credentials
 */

// List of required environment variables
const REQUIRED_VARS = [
  'NODE_ENV',
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY',
  'ANTHROPIC_API_KEY',
  'STRIPE_SECRET_KEY',
  'LOGFIRE_TOKEN'
];

// Validate that required environment variables are present
function validateEnvironment() {
  const missingVars = [];

  REQUIRED_VARS.forEach(varName => {
    if (!process.env[varName]) {
      missingVars.push(varName);
    }
  });

  if (missingVars.length > 0) {
    console.error('❌ Missing required environment variables:');
    missingVars.forEach(varName => console.error(`  - ${varName}`));
    process.exit(1);
  }

  // Check if in test environment
  if (process.env.NODE_ENV === 'test') {
    console.log('✅ Environment validation passed for test environment');
    console.log('⚠️  Note: Using test environment variables (may be canary values)');
    return;
  }

  console.log('✅ All required environment variables are present');
}

// Run validation
validateEnvironment();
